import{_ as r,o as a,c as t,a3 as n}from"./chunks/framework.BrO6lPIi.js";const b=JSON.parse('{"title":"RAG 知识检索","description":"本文件面向“RAG（检索增强生成）知识检索系统”的完整技术文档，覆盖从文档解析、文本分块、向量嵌入、索引构建、向量存储、混合检索到长期记忆注入的全链路。","frontmatter":{"title":"RAG 知识检索","description":"本文件面向“RAG（检索增强生成）知识检索系统”的完整技术文档，覆盖从文档解析、文本分块、向量嵌入、索引构建、向量存储、混合检索到长期记忆注入的全链路。"},"headers":[],"relativePath":"RAG-知识检索/index.md","filePath":"RAG-知识检索/index.md","lastUpdated":null}'),i={name:"RAG-知识检索/index.md"};function l(g,e,o,s,c,h){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="rag-知识检索" tabindex="-1">RAG 知识检索 <a class="header-anchor" href="#rag-知识检索" aria-label="Permalink to &quot;RAG 知识检索&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js" target="_blank" rel="noreferrer">agent/src/rag/config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js" target="_blank" rel="noreferrer">agent/src/rag/manager.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js" target="_blank" rel="noreferrer">agent/src/rag/searcher.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/detect.js" target="_blank" rel="noreferrer">agent/src/rag/detect.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/install.js" target="_blank" rel="noreferrer">agent/src/rag/install.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/embedding/index.js" target="_blank" rel="noreferrer">agent/src/rag/embedding/index.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/store/vectra.js" target="_blank" rel="noreferrer">agent/src/rag/store/vectra.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js" target="_blank" rel="noreferrer">agent/src/memory/service.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/injection.js" target="_blank" rel="noreferrer">agent/src/memory/injection.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/embedding-config.js" target="_blank" rel="noreferrer">agent/src/memory/embedding-config.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与容量特性">性能与容量特性</a></li><li><a href="#知识库管理端到端流程">知识库管理端到端流程</a></li><li>[长期记忆与 RAG 集成](#长期记忆与 rag 集成)</li><li><a href="#向量存储与索引机制">向量存储与索引机制</a></li><li><a href="#混合检索引擎">混合检索引擎</a></li><li><a href="#配置项与监控">配置项与监控</a></li><li><a href="#故障排除指南">故障排除指南</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文件面向“RAG（检索增强生成）知识检索系统”的完整技术文档，覆盖从文档解析、文本分块、向量嵌入、索引构建、向量存储、混合检索到长期记忆注入的全链路。系统采用双进程架构：Chrome 扩展端通过本地 HTTP/WebSocket 调用 Agent 端的 RAG 能力；Agent 端负责实际的文件解析、向量化、索引与检索。所有实现以 agent 源码为准，版本为 2.3.1。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>RAG 相关代码集中在 <code>agent/src/rag</code>，长期记忆在 <code>agent/src/memory</code>，两者通过共享的 embedding provider 和关键词匹配逻辑协作。</p><pre class="mermaid">graph TB
subgraph &quot;Agent 端&quot;
RAG[&quot;RAG 子系统&lt;br/&gt;config / manager / searcher / store / embedding&quot;]
MEMORY[&quot;长期记忆子系统&lt;br/&gt;service / injection / embedding-config&quot;]
DETECT[&quot;依赖检测与安装&lt;br/&gt;detect / install&quot;]
end
subgraph &quot;外部依赖&quot;
VECTRA[&quot;Vectra 本地向量索引&quot;]
EMBED[&quot;Embedding Provider&lt;br/&gt;本地 BGE / OpenAI 兼容&quot;]
end
RAG --&gt; VECTRA
RAG --&gt; EMBED
MEMORY --&gt; EMBED
DETECT --&gt; RAG
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L1-L70" target="_blank" rel="noreferrer">agent/src/rag/config.js#L1-L70</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L1-L100" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L1-L100</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L1-L40" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L1-L40</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/store/vectra.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/store/vectra.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/embedding/index.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/embedding/index.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js#L1-L30" target="_blank" rel="noreferrer">agent/src/memory/service.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/detect.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/detect.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/install.js#L1-L40" target="_blank" rel="noreferrer">agent/src/rag/install.js#L1-L40</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L1-L70" target="_blank" rel="noreferrer">agent/src/rag/config.js#L1-L70</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L1-L100" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L1-L100</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><ul><li><strong>RAG 配置中心</strong>：定义数据根目录、知识库注册表、默认 embedding 配置、默认分块参数、默认检索参数、解析器扩展名路由。</li><li><strong>RagManager</strong>：知识库生命周期管理、文档导入、重建索引、进度上报、安全校验、URL 导入策略。</li><li><strong>Searcher</strong>：语义搜索 + 关键词命中增强 + 阈值过滤 + 旁路探测。</li><li><strong>VectraStore</strong>：Vectra 本地索引适配器，封装事务写入、查询、按文档删除、全量扫描。</li><li><strong>EmbeddingProvider</strong>：统一 embedding 接口，支持本地 BGE 中文模型与 OpenAI 兼容远端。</li><li><strong>MemoryService</strong>：长期记忆的增删改查、召回、审查压缩、分级注入、向量缓存补齐。</li><li><strong>Detect/Install</strong>：RAG 可选依赖检测与一键安装，含自动恢复、进程治理、状态持久化。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L1-L70" target="_blank" rel="noreferrer">agent/src/rag/config.js#L1-L70</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L1-L100" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L1-L100</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L1-L40" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L1-L40</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/store/vectra.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/store/vectra.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/embedding/index.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/embedding/index.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js#L1-L30" target="_blank" rel="noreferrer">agent/src/memory/service.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/detect.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/detect.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/install.js#L1-L40" target="_blank" rel="noreferrer">agent/src/rag/install.js#L1-L40</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>RAG 的知识库由“元数据注册表 + Vectra 索引 + 原始文档备份”组成；长期记忆由 JSON 文件 + 向量派生缓存组成。两者共用 embedding provider，但数据域不同：RAG 面向文档切片，记忆面向事实与摘要。</p><pre class="mermaid">sequenceDiagram
participant Client as &quot;客户端/扩展端&quot;
participant Manager as &quot;RagManager&quot;
participant Loader as &quot;DocumentLoader&quot;
participant Chunker as &quot;Chunker&quot;
participant Embedder as &quot;EmbeddingProvider&quot;
participant Store as &quot;VectraStore&quot;
participant Searcher as &quot;Searcher&quot;
Client-&gt;&gt;Manager : 创建知识库
Manager-&gt;&gt;Store : ensureCreated()
Manager--&gt;&gt;Client : 返回知识库元信息
Client-&gt;&gt;Manager : 导入文档/文本/URL
Manager-&gt;&gt;Loader : loadDocument(filePath)
Loader--&gt;&gt;Manager : {text, fileName}
Manager-&gt;&gt;Chunker : chunkText(text, chunkConfig)
Chunker--&gt;&gt;Manager : chunks[]
Manager-&gt;&gt;Embedder : embedDocuments(chunks)
Embedder--&gt;&gt;Manager : embeddings[][]
Manager-&gt;&gt;Store : upsertChunks(documentId, chunks, embeddings, metadata)
Store--&gt;&gt;Manager : 成功
Client-&gt;&gt;Manager : 检索 query
Manager-&gt;&gt;Searcher : search(query, options)
Searcher-&gt;&gt;Embedder : embedQuery(query)
Searcher-&gt;&gt;Store : search(queryVec, query, topK*2)
Searcher--&gt;&gt;Manager : 结果集
Manager--&gt;&gt;Client : 最终检索结果
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L267-L301" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L267-L301</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L33-L48" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L33-L48</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L31-L75" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L31-L75</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/embedding/index.js#L40-L57" target="_blank" rel="noreferrer">agent/src/rag/embedding/index.js#L40-L57</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/store/vectra.js#L39-L65" target="_blank" rel="noreferrer">agent/src/rag/store/vectra.js#L39-L65</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L46-L77" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L46-L77</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="ragmanager-知识库生命周期与导入重建" tabindex="-1">RagManager：知识库生命周期与导入重建 <a class="header-anchor" href="#ragmanager-知识库生命周期与导入重建" aria-label="Permalink to &quot;RagManager：知识库生命周期与导入重建&quot;">​</a></h3><p>RagManager 是 RAG 的核心编排器，职责包括：</p><ul><li>注册表读写互斥保护，避免并发写坏 collections.json。</li><li>知识库创建/删除/启用切换/更新。</li><li>文档导入：文本、本地文件、上传内容、URL。</li><li>索引重建：临时目录构建新索引 → 原子换入 → 提交注册表 → 清理现场。</li><li>中断恢复：根据 rebuild_manifest 与 index_backup 收敛半完成状态。</li><li>导入进度快照：供前端轮询展示阶段、当前数、总数、错误。</li></ul><p>关键设计点：</p><ul><li>知识库 ID 正则校验，防止路径穿越。</li><li>embedding 配置跨模式重置，防字段污染。</li><li>仅当 mode/endpoint/modelName/dimensions 或 chunkSize/overlap 变化时才触发重建。</li><li>重建失败保留旧索引与旧配置，保证可用性。</li><li>URL 导入受内网放行策略控制，测试可注入覆盖。</li></ul><pre class="mermaid">flowchart TD
Start([&quot;updateCollection&quot;]) --&gt; Validate[&quot;校验名称/描述/配置&quot;]
Validate --&gt; CheckRebuild{&quot;是否需重建索引？&quot;}
CheckRebuild --&gt; |否| UpdateMeta[&quot;直接更新名称/描述/非敏感配置&quot;]
UpdateMeta --&gt; ReturnUpdate[&quot;返回已更新知识库&quot;]
CheckRebuild --&gt; |是| ReportProgress[&quot;上报 rebuilding 进度&quot;]
ReportProgress --&gt; RebuildIndex[&quot;_rebuildIndex(collectionId, nextEmbedding, nextChunk)&quot;]
RebuildIndex --&gt; RecoverInterrupted[&quot;recoverInterruptedRebuild()&quot;]
RecoverInterrupted --&gt; ReadBackups[&quot;读取 documents/ 备份&quot;]
ReadBackups --&gt; BuildNewIndex[&quot;临时目录构建新索引&quot;]
BuildNewIndex --&gt; AtomicSwap[&quot;原子换入：rename(finalDir) → rename(tmpRoot/collectionId)&quot;]
AtomicSwap --&gt; CommitRegistry[&quot;提交注册表：embeddingConfig/chunkCount/documentCount&quot;]
CommitRegistry --&gt; Cleanup[&quot;删除清单/旧索引备份/临时目录&quot;]
Cleanup --&gt; Done([&quot;重建完成&quot;])
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L349-L407" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L349-L407</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L434-L550" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L434-L550</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L561-L640" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L561-L640</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L1-L100" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L1-L100</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L267-L407" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L267-L407</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L434-L640" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L434-L640</a></li></ul><h3 id="文档处理管道-多格式解析与分块" tabindex="-1">文档处理管道：多格式解析与分块 <a class="header-anchor" href="#文档处理管道-多格式解析与分块" aria-label="Permalink to &quot;文档处理管道：多格式解析与分块&quot;">​</a></h3><p>文档处理分为两步：</p><ol><li><strong>加载与解析</strong>：按扩展名路由到 text/html/pdf/office 解析器，输出纯文本。</li><li><strong>分块</strong>：段落优先断点 + 字符窗口兜底 + 重叠回退，返回带原文偏移的分块。</li></ol><p>支持的扩展名由 PARSER_ROUTES 定义，包括 txt/md/json/csv/html/htm/pdf/docx/pptx/xlsx/xls。chunker 默认 chunkSize=400、overlap=80，并警告超过 500 可能静默截断。</p><pre class="mermaid">flowchart TD
Input[&quot;输入文件/文本&quot;] --&gt; Route[&quot;按扩展名路由&quot;]
Route --&gt; Parse[&quot;解析器解析为纯文本&quot;]
Parse --&gt; Normalize[&quot;规范化换行&quot;]
Normalize --&gt; Chunk[&quot;分段优先断点 + 窗口兜底 + 重叠&quot;]
Chunk --&gt; Output[&quot;chunks[{text,startPos,endPos}]&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L8-L48" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L8-L48</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L9-L75" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L9-L75</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L56-L69" target="_blank" rel="noreferrer">agent/src/rag/config.js#L56-L69</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L1-L49" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L1-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L1-L76" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L56-L69" target="_blank" rel="noreferrer">agent/src/rag/config.js#L56-L69</a></li></ul><h3 id="向量嵌入与索引构建" tabindex="-1">向量嵌入与索引构建 <a class="header-anchor" href="#向量嵌入与索引构建" aria-label="Permalink to &quot;向量嵌入与索引构建&quot;">​</a></h3><p>EmbeddingProvider 提供统一接口：</p><ul><li>embedQuery：查询侧自动附加 queryPrefix（BGE 中文模型必须）。</li><li>embedDocuments：文档侧不加前缀。</li><li>支持 local（Xenova/bge-small-zh-v1.5）与 openai-compat（远端）两种后端。</li><li>dimensions=0 表示未显式指定，远端跟随平台默认维度。</li></ul><p>索引构建流程：</p><ul><li>对每个文档分块后批量嵌入。</li><li>使用 VectraStore.upsertChunks 事务写入，metadata 包含 documentId、chunkIndex、totalChunks、text、startPos、endPos。</li><li>重建时先写临时索引，再原子换入，最后提交注册表。</li></ul><pre class="mermaid">classDiagram
class EmbeddingProvider {
+string mode
+string modelName
+number dimensions
+string queryPrefix
+embedQuery(query) number[]
+embedDocuments(texts) number[][]
}
class LocalEmbedding
class OpenAICompatEmbedding
class VectraStore {
+ensureCreated()
+upsertChunks(documentId, chunks, embeddings, metadata)
+search(queryVector, queryText, options)
+listAllItems()
+removeDocument(documentId)
}
EmbeddingProvider &lt;.. LocalEmbedding : &quot;本地 BGE&quot;
EmbeddingProvider &lt;.. OpenAICompatEmbedding : &quot;远端兼容&quot;
RagManager --&gt; EmbeddingProvider : &quot;创建 provider&quot;
RagManager --&gt; VectraStore : &quot;写入索引&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/embedding/index.js#L10-L57" target="_blank" rel="noreferrer">agent/src/rag/embedding/index.js#L10-L57</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/store/vectra.js#L13-L65" target="_blank" rel="noreferrer">agent/src/rag/store/vectra.js#L13-L65</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L463-L489" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L463-L489</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/embedding/index.js#L1-L68" target="_blank" rel="noreferrer">agent/src/rag/embedding/index.js#L1-L68</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/store/vectra.js#L1-L124" target="_blank" rel="noreferrer">agent/src/rag/store/vectra.js#L1-L124</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L434-L550" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L434-L550</a></li></ul><h3 id="向量存储系统-vectra-适配与索引管理" tabindex="-1">向量存储系统：Vectra 适配与索引管理 <a class="header-anchor" href="#向量存储系统-vectra-适配与索引管理" aria-label="Permalink to &quot;向量存储系统：Vectra 适配与索引管理&quot;">​</a></h3><p>VectraStore 是对 vectra@0.15.0 的轻量适配层，关键点：</p><ul><li>createIndex 对已存在索引抛错，因此 ensureCreated 先判 isIndexCreated。</li><li>无批量 upsert API，使用 beginUpdate/endUpdate 事务包裹逐条 upsertItem。</li><li>无按元数据删除 API，通过 listItemsByMetadata + deleteItems 两步删除。</li><li>queryItems 位置参数签名，query 仅 BM25 路径使用。</li><li>metadata 记录 documentId/startPos/endPos，为混合检索预留。</li></ul><p>索引管理机制：</p><ul><li>每个知识库一个目录，包含 Vectra 索引与 documents/ 原始文档备份。</li><li>重建时使用临时目录 <code>.rebuild_&lt;collectionId&gt;</code>，完成后原子换入。</li><li>重建清单 rebuild_manifest.json 用于崩溃恢复。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/store/vectra.js#L1-L124" target="_blank" rel="noreferrer">agent/src/rag/store/vectra.js#L1-L124</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L434-L550" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L434-L550</a></li></ul><h3 id="混合检索引擎-语义搜索、关键词匹配、重排序与阈值过滤" tabindex="-1">混合检索引擎：语义搜索、关键词匹配、重排序与阈值过滤 <a class="header-anchor" href="#混合检索引擎-语义搜索、关键词匹配、重排序与阈值过滤" aria-label="Permalink to &quot;混合检索引擎：语义搜索、关键词匹配、重排序与阈值过滤&quot;">​</a></h3><p>Searcher 实现混合检索：</p><ul><li>语义通道：使用 EmbeddingProvider.embedQuery 生成查询向量，调用 VectraStore.search 获取候选。</li><li>关键词通道：自建关键词匹配（非 Vectra 内置 BM25），英文按词边界，中文取最长命中片段。</li><li>重排序：命中 chunk 抬分（保底 KEYWORD_MIN_SCORE + 单元加分），合并后再统一阈值过滤。</li><li>旁路探测：过滤后为空时放宽阈值，区分“无数据”与“被过滤”。</li></ul><pre class="mermaid">flowchart TD
Query[&quot;查询 query&quot;] --&gt; EmbedQuery[&quot;embedQuery(query)&quot;]
EmbedQuery --&gt; VectorSearch[&quot;store.search(queryVec, query, topK*2)&quot;]
VectorSearch --&gt; Candidates[&quot;候选集合&quot;]
Candidates --&gt; KeywordBoost[&quot;关键词命中增强&quot;]
KeywordBoost --&gt; ThresholdFilter[&quot;阈值过滤 score &gt;= threshold&quot;]
ThresholdFilter --&gt; EmptyCheck{&quot;结果为空？&quot;}
EmptyCheck --&gt; |否| TopK[&quot;取 topK 返回&quot;]
EmptyCheck --&gt; |是| Fallback[&quot;放宽阈值 -0.2，最多 3 条&quot;]
Fallback --&gt; Return[&quot;返回结果 + fallback 标记&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L46-L77" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L46-L77</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L89-L160" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L89-L160</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L1-L162" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L1-L162</a></li></ul><h3 id="依赖检测与安装-rag-可选依赖生命周期" tabindex="-1">依赖检测与安装：RAG 可选依赖生命周期 <a class="header-anchor" href="#依赖检测与安装-rag-可选依赖生命周期" aria-label="Permalink to &quot;依赖检测与安装：RAG 可选依赖生命周期&quot;">​</a></h3><p>RAG 是高级功能，不强制安装。detect.js 在新子进程中探测 vectra 与 @huggingface/transformers 可用性，避免长驻进程内模块求值失败缓存问题。install.js 提供一键安装，包含：</p><ul><li>包清单来自 package.json 的 ragDependencies 字段。</li><li>Windows 优先直执行 npm-cli.js，否则回退 npm.cmd + shell: true。</li><li>异步任务 + 安装锁 + 超时上限 10 分钟。</li><li>状态持久化到 ~/.ai-helper-agent/rag-install-state.json。</li><li>启动时自动恢复：曾成功安装过但依赖丢失时自动重装。</li></ul><pre class="mermaid">stateDiagram-v2
[*] --&gt; Idle
Idle --&gt; Installing : &quot;startRagInstall()&quot;
Installing --&gt; Verifying : &quot;npm 退出码 0&quot;
Verifying --&gt; Done : &quot;detectRagAvailable() = true&quot;
Verifying --&gt; Failed : &quot;detectRagAvailable() = false&quot;
Installing --&gt; Aborted : &quot;stopRagInstall()&quot;
Failed --&gt; Idle : &quot;重新安装&quot;
Aborted --&gt; Idle : &quot;重新安装&quot;
Done --&gt; Idle : &quot;自动恢复检查&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/detect.js#L76-L168" target="_blank" rel="noreferrer">agent/src/rag/detect.js#L76-L168</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/install.js#L239-L391" target="_blank" rel="noreferrer">agent/src/rag/install.js#L239-L391</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/detect.js#L1-L193" target="_blank" rel="noreferrer">agent/src/rag/detect.js#L1-L193</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/install.js#L1-L461" target="_blank" rel="noreferrer">agent/src/rag/install.js#L1-L461</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><p>RAG 与长期记忆共享 embedding provider，但数据域独立。RAG 依赖 Vectra 本地索引与 transformers.js 模型缓存；长期记忆依赖 JSON 文件与向量派生缓存。</p><pre class="mermaid">graph LR
RAG[&quot;RAG 子系统&quot;] --&gt; VECTOR[&quot;Vectra 索引&quot;]
RAG --&gt; EMBED[&quot;EmbeddingProvider&quot;]
MEMORY[&quot;长期记忆子系统&quot;] --&gt; EMBED
MEMORY --&gt; JSON[&quot;global-memory.json&quot;]
MEMORY --&gt; VEC_CACHE[&quot;向量派生缓存&quot;]
DETECT[&quot;detect/install&quot;] --&gt; RAG
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/embedding/index.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/embedding/index.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js#L1-L30" target="_blank" rel="noreferrer">agent/src/memory/service.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/detect.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/detect.js#L1-L30</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/embedding/index.js#L1-L68" target="_blank" rel="noreferrer">agent/src/rag/embedding/index.js#L1-L68</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js#L1-L30" target="_blank" rel="noreferrer">agent/src/memory/service.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/detect.js#L1-L30" target="_blank" rel="noreferrer">agent/src/rag/detect.js#L1-L30</a></li></ul><h2 id="性能与容量特性" tabindex="-1">性能与容量特性 <a class="header-anchor" href="#性能与容量特性" aria-label="Permalink to &quot;性能与容量特性&quot;">​</a></h2><ul><li><strong>分块大小</strong>：默认 400 字符，最大 2000，超过 500 告警（bge-small-zh-v1.5 最大 512 token）。</li><li><strong>嵌入批大小</strong>：固定 10，兼容阿里云百炼等平台单次批量上限。</li><li><strong>检索 topK 上限</strong>：SEARCH_TOPK_MAX=50，防止超大 topK 放大候选集。</li><li><strong>关键词扫描限制</strong>：KEYWORD_SCAN_LIMIT=20000，超过则跳过关键词通道。</li><li><strong>导入体积上限</strong>：文本 10MB，上传 50MB，防止 OOM。</li><li><strong>重建原子性</strong>：临时目录 + 原子换入 + 清单恢复，崩溃后可收敛。</li><li><strong>记忆召回锁外嵌入</strong>：避免外部网络调用阻塞同进程所有写入。</li></ul><p>[本节为通用性能讨论，不直接分析具体文件]</p><h2 id="知识库管理端到端流程" tabindex="-1">知识库管理端到端流程 <a class="header-anchor" href="#知识库管理端到端流程" aria-label="Permalink to &quot;知识库管理端到端流程&quot;">​</a></h2><p>以下示例展示从文档上传到查询响应的完整流程：</p><pre class="mermaid">sequenceDiagram
participant User as &quot;用户&quot;
participant UI as &quot;扩展端 UI&quot;
participant Agent as &quot;Agent 服务端&quot;
participant Manager as &quot;RagManager&quot;
participant Loader as &quot;DocumentLoader&quot;
participant Chunker as &quot;Chunker&quot;
participant Embedder as &quot;EmbeddingProvider&quot;
participant Store as &quot;VectraStore&quot;
participant Searcher as &quot;Searcher&quot;
User-&gt;&gt;UI : 选择 PDF/Office/文本文件
UI-&gt;&gt;Agent : POST /api/rag/ingest (collectionId, fileBase64)
Agent-&gt;&gt;Manager : ingestFile(collectionId, input)
Manager-&gt;&gt;Loader : loadDocument(filePath)
Loader--&gt;&gt;Manager : {text, fileName}
Manager-&gt;&gt;Chunker : chunkText(text, chunkConfig)
Chunker--&gt;&gt;Manager : chunks[]
Manager-&gt;&gt;Embedder : embedDocuments(chunks)
Embedder--&gt;&gt;Manager : embeddings[][]
Manager-&gt;&gt;Store : upsertChunks(documentId, chunks, embeddings, metadata)
Store--&gt;&gt;Manager : 成功
Manager--&gt;&gt;Agent : 返回 documentId/chunkCount
Agent--&gt;&gt;UI : 导入成功
User-&gt;&gt;UI : 输入查询
UI-&gt;&gt;Agent : GET /api/rag/search (collectionId, query, topK, threshold)
Agent-&gt;&gt;Manager : search(collectionId, query, options)
Manager-&gt;&gt;Searcher : search(query, options)
Searcher-&gt;&gt;Embedder : embedQuery(query)
Searcher-&gt;&gt;Store : search(queryVec, query, topK*2)
Searcher--&gt;&gt;Manager : 结果集
Manager--&gt;&gt;Agent : 最终结果
Agent--&gt;&gt;UI : 返回检索结果
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L723-L790" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L723-L790</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/loader.js#L33-L48" target="_blank" rel="noreferrer">agent/src/rag/document/loader.js#L33-L48</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/document/chunker.js#L31-L75" target="_blank" rel="noreferrer">agent/src/rag/document/chunker.js#L31-L75</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/embedding/index.js#L40-L57" target="_blank" rel="noreferrer">agent/src/rag/embedding/index.js#L40-L57</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/store/vectra.js#L39-L65" target="_blank" rel="noreferrer">agent/src/rag/store/vectra.js#L39-L65</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L46-L77" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L46-L77</a></li></ul><h2 id="长期记忆与-rag-集成" tabindex="-1">长期记忆与 RAG 集成 <a class="header-anchor" href="#长期记忆与-rag-集成" aria-label="Permalink to &quot;长期记忆与 RAG 集成&quot;">​</a></h2><p>长期记忆服务 MemoryService 提供：</p><ul><li><strong>store</strong>：新增/更新/删除记忆，含注入模式拦截、频率限制、去重。</li><li><strong>recall</strong>：关键词通道 + 可选向量通道（RRF 融合），会话级去重，访问计数更新。</li><li><strong>manage</strong>：审查价值分数、压缩淘汰低价值记忆。</li><li><strong>injectSelect</strong>：三级注入策略（Tier1 常驻、Tier2 预算内、Tier3 按需）。</li><li><strong>backfillVectors</strong>：显式重建向量缓存，支持超窗检测。</li><li><strong>vectorStatus</strong>：只读状态，判断向量缓存是否陈旧。</li></ul><p>与 RAG 的集成点：</p><ul><li>共享 EmbeddingProvider，支持本地 BGE 与 OpenAI 兼容远端。</li><li>记忆召回可降级为关键词单通道，不影响正确性。</li><li>记忆向量缓存与 RAG 索引独立，但都依赖同一 embedding 配置。</li></ul><pre class="mermaid">flowchart TD
Recall[&quot;recall(query, tags, memoryType, limit)&quot;] --&gt; TierCheck[&quot;判定 tierlocal/openai-compat&quot;]
TierCheck --&gt; EmbedQuery[&quot;embedQuery(query)&quot;]
EmbedQuery --&gt; LockRead[&quot;锁内只读：读真源、定候选、校验向量指纹&quot;]
LockRead --&gt; Backfill[&quot;锁外补齐缺失向量冷却 60s&quot;]
Backfill --&gt; Fuse[&quot;RRF 融合：关键词排名 + 语义排名&quot;]
Fuse --&gt; TagLift[&quot;标签名次加成&quot;]
TagLift --&gt; Dedup[&quot;会话去重 + 全局去重&quot;]
Dedup --&gt; UpdateAccess[&quot;更新访问计数&quot;]
UpdateAccess --&gt; Return[&quot;返回结果 + tier + vectorMatched&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js#L473-L740" target="_blank" rel="noreferrer">agent/src/memory/service.js#L473-L740</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/injection.js#L84-L128" target="_blank" rel="noreferrer">agent/src/memory/injection.js#L84-L128</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/embedding-config.js#L21-L95" target="_blank" rel="noreferrer">agent/src/memory/embedding-config.js#L21-L95</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js#L1-L1013" target="_blank" rel="noreferrer">agent/src/memory/service.js#L1-L1013</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/injection.js#L1-L129" target="_blank" rel="noreferrer">agent/src/memory/injection.js#L1-L129</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/embedding-config.js#L1-L96" target="_blank" rel="noreferrer">agent/src/memory/embedding-config.js#L1-L96</a></li></ul><h2 id="向量存储与索引机制" tabindex="-1">向量存储与索引机制 <a class="header-anchor" href="#向量存储与索引机制" aria-label="Permalink to &quot;向量存储与索引机制&quot;">​</a></h2><p>VectraStore 封装了 Vectra 本地索引的关键操作：</p><ul><li><strong>ensureCreated</strong>：幂等创建索引。</li><li><strong>upsertChunks</strong>：事务批量写入分块，metadata 包含文档标识与分块信息。</li><li><strong>search</strong>：向量检索，返回统一结构。</li><li><strong>listDocumentChunks</strong>：按文档列出分块。</li><li><strong>removeDocument</strong>：按文档删除所有分块。</li><li><strong>listAllItems</strong>：全量扫描，用于关键词通道统计。</li><li><strong>recreate</strong>：清空重建，用于模型变更后强制重建。</li></ul><p>索引管理机制：</p><ul><li>每个知识库一个目录，包含 Vectra 索引与 documents/ 原始文档备份。</li><li>重建时使用临时目录，完成后原子换入。</li><li>重建清单用于崩溃恢复，确保注册表与索引一致。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/store/vectra.js#L1-L124" target="_blank" rel="noreferrer">agent/src/rag/store/vectra.js#L1-L124</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L434-L640" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L434-L640</a></li></ul><h2 id="混合检索引擎" tabindex="-1">混合检索引擎 <a class="header-anchor" href="#混合检索引擎" aria-label="Permalink to &quot;混合检索引擎&quot;">​</a></h2><p>Searcher 实现混合检索的核心逻辑：</p><ul><li><strong>语义搜索</strong>：使用 EmbeddingProvider.embedQuery 生成查询向量，调用 VectraStore.search 获取候选。</li><li><strong>关键词匹配</strong>：自建关键词匹配，英文按词边界，中文取最长命中片段，高频词剔除。</li><li><strong>重排序</strong>：命中 chunk 抬分（保底 KEYWORD_MIN_SCORE + 单元加分），合并后再统一阈值过滤。</li><li><strong>旁路探测</strong>：过滤后为空时放宽阈值，区分“无数据”与“被过滤”。</li></ul><pre class="mermaid">flowchart TD
Query[&quot;查询 query&quot;] --&gt; ExtractTerms[&quot;提取拉丁/CJK 术语&quot;]
ExtractTerms --&gt; VectorSearch[&quot;向量检索 topK*2&quot;]
VectorSearch --&gt; KeywordScan[&quot;全量扫描 chunks≤20000&quot;]
KeywordScan --&gt; Boost[&quot;命中 chunk 抬分&quot;]
Boost --&gt; Merge[&quot;合并候选 + 重排&quot;]
Merge --&gt; Filter[&quot;阈值过滤&quot;]
Filter --&gt; Fallback{&quot;结果为空？&quot;}
Fallback --&gt; |是| Relax[&quot;放宽阈值 -0.2&quot;]
Fallback --&gt; |否| TopK[&quot;取 topK&quot;]
Relax --&gt; Return[&quot;返回结果 + fallback 标记&quot;]
TopK --&gt; Return
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L46-L77" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L46-L77</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L89-L160" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L89-L160</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L1-L162" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L1-L162</a></li></ul><h2 id="配置项与监控" tabindex="-1">配置项与监控 <a class="header-anchor" href="#配置项与监控" aria-label="Permalink to &quot;配置项与监控&quot;">​</a></h2><h3 id="rag-配置项" tabindex="-1">RAG 配置项 <a class="header-anchor" href="#rag-配置项" aria-label="Permalink to &quot;RAG 配置项&quot;">​</a></h3><ul><li><strong>RAG_ROOT</strong>：数据根目录，可通过环境变量 AI_HELPER_RAG_ROOT 覆盖。</li><li><strong>COLLECTIONS_REGISTRY</strong>：知识库注册表文件。</li><li><strong>MODELS_DIR</strong>：transformers.js 模型缓存目录。</li><li><strong>DEFAULT_EMBEDDING_CONFIG</strong>：默认 embedding 配置（本地 BGE 中文模型）。</li><li><strong>DEFAULT_CHUNK_CONFIG</strong>：默认分块参数（chunkSize=400, overlap=80）。</li><li><strong>DEFAULT_SEARCH_CONFIG</strong>：默认检索参数（topK=5, threshold=0.3）。</li><li><strong>EMBED_BATCH_SIZE</strong>：嵌入批大小（固定 10）。</li><li><strong>PARSER_ROUTES</strong>：解析器扩展名路由表。</li></ul><h3 id="长期记忆配置项" tabindex="-1">长期记忆配置项 <a class="header-anchor" href="#长期记忆配置项" aria-label="Permalink to &quot;长期记忆配置项&quot;">​</a></h3><ul><li><strong>DEFAULT_MEMORY_EMBEDDING_CONFIG</strong>：默认记忆 embedding 配置（enabled=false）。</li><li><strong>MEMORY_EMBEDDING_MODES</strong>：mode 白名单（openai-compat/local）。</li><li><strong>MEMORY_INJECTION_CONFIG</strong>：三级注入策略配置（alwaysInjectImportance=8, budgetChars=1500, budgetCount=12）。</li></ul><h3 id="监控与诊断" tabindex="-1">监控与诊断 <a class="header-anchor" href="#监控与诊断" aria-label="Permalink to &quot;监控与诊断&quot;">​</a></h3><ul><li><strong>依赖检测</strong>：detectRagAvailable() 返回 ok/detail/errorSummary。</li><li><strong>安装状态</strong>：getRagInstallStatus() 返回 running/done/success/phase/logTail。</li><li><strong>重建进度</strong>：_reportProgress() 上报 phase/current/total/done/error。</li><li><strong>向量状态</strong>：vectorStatus() 返回 indexed/total/storedModelKey/currentModelKey/stale/tier。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/config.js#L1-L70" target="_blank" rel="noreferrer">agent/src/rag/config.js#L1-L70</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/embedding-config.js#L1-L96" target="_blank" rel="noreferrer">agent/src/memory/embedding-config.js#L1-L96</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/injection.js#L1-L129" target="_blank" rel="noreferrer">agent/src/memory/injection.js#L1-L129</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/detect.js#L76-L193" target="_blank" rel="noreferrer">agent/src/rag/detect.js#L76-L193</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/install.js#L278-L391" target="_blank" rel="noreferrer">agent/src/rag/install.js#L278-L391</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js#L976-L995" target="_blank" rel="noreferrer">agent/src/memory/service.js#L976-L995</a></li></ul><h2 id="故障排除指南" tabindex="-1">故障排除指南 <a class="header-anchor" href="#故障排除指南" aria-label="Permalink to &quot;故障排除指南&quot;">​</a></h2><h3 id="rag-依赖不可用" tabindex="-1">RAG 依赖不可用 <a class="header-anchor" href="#rag-依赖不可用" aria-label="Permalink to &quot;RAG 依赖不可用&quot;">​</a></h3><ul><li><strong>现象</strong>：detectRagAvailable() 返回 false，errorSummary 包含 vectra 或 @huggingface/transformers 错误。</li><li><strong>排查</strong>： <ul><li>检查 Node 版本是否 ≥22。</li><li>运行 startRagInstall() 一键安装。</li><li>查看 getRagInstallStatus().logTail 末尾日志。</li><li>若自动恢复失败，检查 everSucceeded 标记与持久化状态文件。</li></ul></li></ul><h3 id="索引重建失败" tabindex="-1">索引重建失败 <a class="header-anchor" href="#索引重建失败" aria-label="Permalink to &quot;索引重建失败&quot;">​</a></h3><ul><li><strong>现象</strong>：updateCollection() 返回 rebuilding=true，但 _reportProgress() 上报 error。</li><li><strong>排查</strong>： <ul><li>检查 documents/ 备份是否损坏。</li><li>查看临时目录 .rebuild_&lt;collectionId&gt; 是否残留。</li><li>确认 rebuild_manifest.json 是否有效。</li><li>手动清理临时目录后重试。</li></ul></li></ul><h3 id="检索结果为空" tabindex="-1">检索结果为空 <a class="header-anchor" href="#检索结果为空" aria-label="Permalink to &quot;检索结果为空&quot;">​</a></h3><ul><li><strong>现象</strong>：Searcher.search() 返回 total=0，fallback=false。</li><li><strong>排查</strong>： <ul><li>检查 threshold 是否过高。</li><li>检查 embedding 维度是否与索引一致。</li><li>检查关键词通道是否因高频词剔除而失效。</li><li>尝试放宽阈值或关闭关键词通道。</li></ul></li></ul><h3 id="长期记忆召回异常" tabindex="-1">长期记忆召回异常 <a class="header-anchor" href="#长期记忆召回异常" aria-label="Permalink to &quot;长期记忆召回异常&quot;">​</a></h3><ul><li><strong>现象</strong>：recall() 返回 vectorMatched=0 或结果不符合预期。</li><li><strong>排查</strong>： <ul><li>检查 memoryEmbedding.enabled 是否开启。</li><li>检查 backfillVectors() 是否成功。</li><li>查看 vectorStatus().stale 是否为 true。</li><li>检查关键词通道是否因 df 过滤而误伤。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/detect.js#L76-L193" target="_blank" rel="noreferrer">agent/src/rag/detect.js#L76-L193</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/install.js#L278-L461" target="_blank" rel="noreferrer">agent/src/rag/install.js#L278-L461</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/manager.js#L434-L640" target="_blank" rel="noreferrer">agent/src/rag/manager.js#L434-L640</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/rag/searcher.js#L46-L160" target="_blank" rel="noreferrer">agent/src/rag/searcher.js#L46-L160</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/service.js#L473-L995" target="_blank" rel="noreferrer">agent/src/memory/service.js#L473-L995</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>RAG 知识检索系统在文档处理、向量嵌入、索引构建、混合检索、长期记忆注入等方面提供了完整的技术实现。系统强调安全性（沙箱校验、路径穿越防护）、可靠性（原子换入、崩溃恢复）、可观测性（进度上报、状态查询）与可扩展性（本地/远端 embedding 双模式）。通过 Vectra 本地索引与自建关键词通道，系统在中文场景下实现了语义与精确匹配的平衡。长期记忆与 RAG 共享 embedding provider，但数据域独立，便于独立演进与故障隔离。</p>`,137)])])}const m=r(i,[["render",l]]);export{b as __pageData,m as default};
